        "text": "These mosses are the stars of peatlands. While other mosses live in peatlands too—like Hypnum and Polytrichum—the unique traits of Sphagnum make it the top player in these ecosystems, especially peatlands far from the equator. It is mind-blowing that tiny mosses can make entire peatlands. They are like powerful sponges that can suck up lots of water. Mosses also lower the pH of the water around them, further slowing down the decay of dead plants and animals. They are even happy in spots with little food because they are like food catchers—grabbing whatever bits of food come their way. This makes it hard for other plants to live next to Sphagnum, allowing it to grow in fluffy carpets."
