      "citation": "Hall LA, De La Cruz SEW, Woo I, Kuwae T, Nelson DM and Takekawa JY (2021) Small Shorebirds Feast On Green Slime To Fuel Their Long Migration. Front. Young Minds. 9:611826. doi: 10.3389/frym.2021.611826",
